if (!defined('ABSPATH')) exit;

final class HandwerkPilot_Core {
 const TYPE='hp_request'; const NONCE='hp_submit_request';
 private array $statuses=['neu'=>'Neu','pruefung'=>'In Prüfung','termin'=>'Termin vereinbart','erledigt'=>'Erledigt','abgelehnt'=>'Abgelehnt'];
 public function __construct(){add_action('init',[$this,'register_type']);add_shortcode('handwerkpilot_form',[$this,'form']);add_action('admin_post_nopriv_hp_submit',[$this,'submit']);add_action('admin_post_hp_submit',[$this,'submit']);add_action('add_meta_boxes',[$this,'meta_boxes']);add_action('save_post_'.self::TYPE,[$this,'save_admin']);add_filter('manage_'.self::TYPE.'_posts_columns',[$this,'columns']);add_action('manage_'.self::TYPE.'_posts_custom_column',[$this,'column'],10,2);add_action('restrict_manage_posts',[$this,'filter']);add_action('pre_get_posts',[$this,'filter_query']);add_filter('views_edit-'.self::TYPE,[$this,'new_count']);add_action('admin_menu',[$this,'export_menu']);add_action('admin_post_hp_export',[$this,'export']);add_action('wp_enqueue_scripts',[$this,'assets']);}
 public function register_type(){register_post_type(self::TYPE,['labels'=>['name'=>'Serviceanfragen','singular_name'=>'Serviceanfrage','menu_name'=>'Serviceanfragen','add_new_item'=>'Neue Serviceanfrage','edit_item'=>'Serviceanfrage bearbeiten','search_items'=>'Anfragen suchen','not_found'=>'Keine Anfragen gefunden'],'public'=>false,'show_ui'=>true,'show_in_menu'=>true,'menu_icon'=>'dashicons-clipboard','supports'=>['title'],'capability_type'=>'post','map_meta_cap'=>true]);}
 public function assets(){if(!is_admin()){wp_enqueue_script('hp-form',plugins_url('assets/form.js',__FILE__),[], '1.0.0',true);}}
 public function form(){if(!post_type_exists(self::TYPE))return '<p class="hp-error">Das Anfrage-Modul ist derzeit nicht verfügbar</p>';ob_start();$msg=isset($_GET['hp_status'])?sanitize_key(wp_unslash($_GET['hp_status'])):'';if($msg==='success')echo '<div class="hp-alert hp-success" role="status">Vielen Dank! Ihre Demo-Anfrage wurde gespeichert</div>';elseif($msg==='error')echo '<div class="hp-alert hp-error" role="alert">Bitte prüfen Sie Ihre Angaben und versuchen Sie es erneut</div>'; ?>
 <form class="request-shell hp-form" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" method="post" enctype="multipart/form-data" novalidate><input type="hidden" name="action" value="hp_submit"><?php wp_nonce_field(self::NONCE,'hp_nonce'); ?><div class="hp-progress" aria-label="Fortschritt"><?php for($i=1;$i<=6;$i++)echo '<span'.($i===1?' class="active"':'').'></span>'; ?></div>
 <section class="hp-step active" data-step="1"><h3>1. Welche Leistung benötigen Sie?</h3><div class="hp-options"><?php foreach(['diagnose'=>'Störung & Diagnose','steckdose'=>'Steckdose oder Schalter','leuchte'=>'Leuchtenmontage','sonstiges'=>'Andere Elektroarbeit'] as $v=>$l)echo '<label class="hp-option"><input required type="radio" name="service" value="'.esc_attr($v).'"> '.esc_html($l).'</label>'; ?></div></section>
 <section class="hp-step" data-step="2"><h3>2. Problem beschreiben</h3><div class="field"><label for="hp-description">Was ist passiert?</label><textarea id="hp-description" name="description" minlength="10" maxlength="2000" required></textarea></div></section>
 <section class="hp-step" data-step="3"><h3>3. Dringlichkeit & Termin</h3><div class="field"><label for="hp-urgency">Dringlichkeit</label><select id="hp-urgency" name="urgency" required><option value="normal">Normal</option><option value="urgent">Dringend (+ 40 € Demo-Zuschlag)</option></select></div><div class="field"><label for="hp-date">Wunschtermin</label><input id="hp-date" type="date" name="preferred_date" min="<?php echo esc_attr(wp_date('Y-m-d')); ?>" required></div></section>
 <section class="hp-step" data-step="4"><h3>4. Foto hinzufügen (optional)</h3><div class="field"><label for="hp-photo">JPG, PNG oder WebP, max. 5 MB</label><input id="hp-photo" type="file" name="photo" accept="image/jpeg,image/png,image/webp"></div></section>
 <section class="hp-step" data-step="5"><h3>5. Kontaktdaten</h3><div class="field"><label for="hp-name">Name</label><input id="hp-name" name="customer_name" autocomplete="name" maxlength="100" required></div><div class="field"><label for="hp-email">E-Mail</label><input id="hp-email" type="email" name="email" autocomplete="email" required></div><div class="field"><label for="hp-phone">Telefon</label><input id="hp-phone" type="tel" name="phone" autocomplete="tel" maxlength="40" required></div><div class="field"><label><input type="checkbox" name="privacy" value="1" required> Ich stimme der Verarbeitung meiner Angaben im Rahmen dieses Demo-Projekts zu.</label></div><div class="screen-reader-text" aria-hidden="true"><label>Nicht ausfüllen <input name="website" tabindex="-1" autocomplete="off"></label></div></section>
 <section class="hp-step" data-step="6"><h3>6. Angaben prüfen</h3><div data-summary></div><p class="small">Mit dem Absenden wird eine Demo-Anfrage im WordPress-Backend angelegt</p></section><div class="hp-nav"><button type="button" class="button ghost" data-prev hidden>Zurück</button><button type="button" class="button" data-next>Weiter</button><button type="submit" class="button accent" data-submit hidden>Anfrage absenden</button></div></form><?php return ob_get_clean();}
 private function redirect(string $status){$url=wp_get_referer()?:home_url('/');wp_safe_redirect(add_query_arg('hp_status',$status,$url).'#anfrage');exit;}
 public function submit(){if(!isset($_POST['hp_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['hp_nonce'])),self::NONCE))$this->redirect('error');if(!empty($_POST['website']))$this->redirect('success');$service=sanitize_key($_POST['service']??'');$allowed=['diagnose','steckdose','leuchte','sonstiges'];$description=sanitize_textarea_field(wp_unslash($_POST['description']??''));$urgency=sanitize_key($_POST['urgency']??'');$date=sanitize_text_field(wp_unslash($_POST['preferred_date']??''));$name=sanitize_text_field(wp_unslash($_POST['customer_name']??''));$email=sanitize_email(wp_unslash($_POST['email']??''));$phone=sanitize_text_field(wp_unslash($_POST['phone']??''));$valid_date=DateTime::createFromFormat('Y-m-d',$date);$today=wp_date('Y-m-d');if(!in_array($service,$allowed,true)||mb_strlen($description)<10||!in_array($urgency,['normal','urgent'],true)||!$valid_date||$valid_date->format('Y-m-d')!==$date||$date<$today||!$name||!is_email($email)||!$phone||empty($_POST['privacy']))$this->redirect('error');$id=wp_insert_post(['post_type'=>self::TYPE,'post_status'=>'private','post_title'=>sprintf('Anfrage – %s – %s',$name,wp_date('d.m.Y'))],true);if(is_wp_error($id))$this->redirect('error');foreach(['service'=>$service,'description'=>$description,'urgency'=>$urgency,'preferred_date'=>$date,'customer_name'=>$name,'email'=>$email,'phone'=>$phone,'status'=>'neu'] as $k=>$v)update_post_meta($id,'_hp_'.$k,$v);if(!empty($_FILES['photo']['name'])&&($_FILES['photo']['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_OK){if((int)$_FILES['photo']['size']<=5*MB_IN_BYTES){require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$attachment=media_handle_upload('photo',$id,[],['test_form'=>false,'mimes'=>['jpg|jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp']]);if(!is_wp_error($attachment))update_post_meta($id,'_hp_photo_id',(int)$attachment);}}$this->redirect('success');}
 public function meta_boxes(){add_meta_box('hp_request_details','Anfragedetails',[$this,'details_box'],self::TYPE,'normal','high');add_meta_box('hp_request_workflow','Bearbeitung',[$this,'workflow_box'],self::TYPE,'side','high');}
 public function details_box($post){$fields=['service'=>'Leistung','description'=>'Beschreibung','urgency'=>'Dringlichkeit','preferred_date'=>'Wunschtermin','customer_name'=>'Name','email'=>'E-Mail','phone'=>'Telefon'];echo '<table class="widefat striped"><tbody>';foreach($fields as $k=>$l)echo '<tr><th>'.esc_html($l).'</th><td>'.nl2br(esc_html(get_post_meta($post->ID,'_hp_'.$k,true))).'</td></tr>';echo '</tbody></table>'; $photo=(int)get_post_meta($post->ID,'_hp_photo_id',true);if($photo)echo wp_get_attachment_image($photo,'medium',['style'=>'margin-top:16px;max-width:100%;height:auto']);}
 public function workflow_box($post){wp_nonce_field('hp_save_admin','hp_admin_nonce');$current=get_post_meta($post->ID,'_hp_status',true)?:'neu';echo '<p><label for="hp-status"><strong>Status</strong></label></p><select id="hp-status" name="hp_status" style="width:100%">';foreach($this->statuses as $v=>$l)echo '<option value="'.esc_attr($v).'" '.selected($current,$v,false).'>'.esc_html($l).'</option>';echo '</select><p><label for="hp-notes"><strong>Admin-Notizen</strong></label></p><textarea id="hp-notes" name="hp_notes" rows="7" style="width:100%">'.esc_textarea(get_post_meta($post->ID,'_hp_notes',true)).'</textarea>';}
 public function save_admin($id){if(!isset($_POST['hp_admin_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['hp_admin_nonce'])),'hp_save_admin')||!current_user_can('edit_post',$id)||wp_is_post_autosave($id)||wp_is_post_revision($id))return;$status=sanitize_key($_POST['hp_status']??'');if(isset($this->statuses[$status]))update_post_meta($id,'_hp_status',$status);update_post_meta($id,'_hp_notes',sanitize_textarea_field(wp_unslash($_POST['hp_notes']??'')));}
 public function columns($cols){return ['cb'=>$cols['cb'],'title'=>'Anfrage','hp_service'=>'Leistung','hp_date'=>'Wunschtermin','hp_urgency'=>'Dringlichkeit','hp_status'=>'Status','date'=>'Eingang'];}
 public function column($col,$id){$key=str_replace('hp_','',$col);$value=get_post_meta($id,'_hp_'.$key,true);if($col==='hp_status')$value=$this->statuses[$value]??$value;echo esc_html($value?:'—');}
 public function filter($type){if($type!==self::TYPE)return;$current=sanitize_key($_GET['hp_status']??'');echo '<select name="hp_status"><option value="">Alle Status</option>';foreach($this->statuses as $v=>$l)echo '<option value="'.esc_attr($v).'" '.selected($current,$v,false).'>'.esc_html($l).'</option>';echo '</select>';}
 public function filter_query($query){if(!is_admin()||!$query->is_main_query()||$query->get('post_type')!==self::TYPE)return;$status=sanitize_key($_GET['hp_status']??'');if(isset($this->statuses[$status]))$query->set('meta_query',[['key'=>'_hp_status','value'=>$status]]);}
 public function new_count($views){$q=new WP_Query(['post_type'=>self::TYPE,'post_status'=>'private','meta_key'=>'_hp_status','meta_value'=>'neu','fields'=>'ids','posts_per_page'=>1]);$views['hp_new']='<a href="'.esc_url(admin_url('edit.php?post_type='.self::TYPE.'&hp_status=neu')).'">Neu <span class="count">('.(int)$q->found_posts.')</span></a>';return $views;}
 public function export_menu(){add_submenu_page('edit.php?post_type='.self::TYPE,'CSV exportieren','CSV exportieren','manage_options','hp-export',[$this,'export_page']);}
 public function export_page(){echo '<div class="wrap"><h1>Serviceanfragen exportieren</h1><p>Exportiert alle Anfragen als UTF-8-CSV</p><a class="button button-primary" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=hp_export'),'hp_export')).'">CSV herunterladen</a></div>';}
 public function export(){if(!current_user_can('manage_options')||!check_admin_referer('hp_export'))wp_die('Nicht erlaubt.');$items=get_posts(['post_type'=>self::TYPE,'post_status'=>'private','numberposts'=>-1,'orderby'=>'date','order'=>'DESC']);nocache_headers();header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=serviceanfragen-'.wp_date('Y-m-d').'.csv');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['ID','Eingang','Name','E-Mail','Telefon','Leistung','Dringlichkeit','Wunschtermin','Status','Beschreibung','Admin-Notizen'],';');foreach($items as $p){$m=fn($k)=>get_post_meta($p->ID,'_hp_'.$k,true);fputcsv($out,[$p->ID,$p->post_date,$m('customer_name'),$m('email'),$m('phone'),$m('service'),$m('urgency'),$m('preferred_date'),$this->statuses[$m('status')]??$m('status'),$m('description'),$m('notes')],';');}fclose($out);exit;}
}
new HandwerkPilot_Core();
